import { appendAmpMessages, } from "../chatSessions/ampTranscript.js";
import { ampTranscriptPath, isArmed } from "../chatSessions/arming.js";
import { armSession, isLocalCaptureDisabled, } from "../chatSessions/index.js";
import { runCaptureHook } from "./captureHook.js";
import { runUserPromptSubmit } from "./userPromptSubmit.js";
function ampHookInput(args, extra) {
    return {
        session_id: args.threadId,
        transcript_path: ampTranscriptPath(args.threadId),
        cwd: args.cwd ?? process.cwd(),
        ...extra,
    };
}
function runAmpCapture(hookType, args, extra) {
    return runCaptureHook(hookType, "amp", ampHookInput(args, extra), args.pluginVersion);
}
export function captureAmpSessionStart(args) {
    return runAmpCapture("SessionStart", args);
}
